'use strict';
let firstWeekFilter='all',firstType='all',firstProgress='all',firstSource='all',firstSearch='',firstPage=0;
function firstQuestionType(q){return q.code?'code':'concept';}
function firstFiltered(){const needle=firstSearch.trim().toLowerCase();return FIRST_HALF_MCQS.filter(q=>(firstWeekFilter==='all'||firstWeek(q)===Number(firstWeekFilter))&&(firstType==='all'||firstQuestionType(q)===firstType)&&(firstSource==='all'||(firstSource==='studio'?!q.bank:q.bank===firstSource))&&(firstProgress==='all'||(firstProgress==='new'?!state.records[q.id]:firstProgress==='missed'?state.records[q.id]&&!state.records[q.id].latestCorrect:state.records[q.id]?.latestCorrect))&&(!needle||[q.id,q.title,q.code,topicOf(q.topic).name].join(' ').toLowerCase().includes(needle)));}
function renderFirstList(){const qs=firstFiltered(),size=20;firstPage=Math.min(firstPage,Math.max(0,Math.ceil(qs.length/size)-1));document.getElementById('first-count').textContent=qs.length+' matching questions';document.getElementById('first-list').innerHTML=qs.slice(firstPage*size,(firstPage+1)*size).map(q=>`<button class="exercise-card" data-first-question="${q.id}"><span class="tag">Week ${firstWeek(q)} · ${firstQuestionType(q)==='code'?'Code question':'Concept'}</span><h3>${esc(q.title)}</h3><span class="card-bottom"><span>${state.records[q.id]?.latestCorrect?'✓ Correct':state.records[q.id]?'Revisit':'Not attempted'}</span><span aria-hidden="true">→</span></span></button>`).join('')||'<p class="empty">No questions match. Try changing the filters.</p>';document.getElementById('first-pagination').innerHTML=qs.length>size?`<div class="actions"><button class="secondary" data-first-page="${firstPage-1}" ${firstPage===0?'disabled':''}>← Previous</button><span class="muted">Page ${firstPage+1} of ${Math.ceil(qs.length/size)}</span><button class="secondary" data-first-page="${firstPage+1}" ${(firstPage+1)*size>=qs.length?'disabled':''}>Next →</button></div>`:'';}
function originalMockCards(){return `<details class="panel original-sets"><summary>Explore the earlier Mock A–D collections</summary><p>These ${IMPORTED_MCQS.length} questions are included in the weekly totals. Their original programs, wording, choices, and explanations remain available.</p><div class="bank-grid">${['A','B','C','D'].map(bank=>{const qs=IMPORTED_MCQS.filter(q=>q.bank===bank),programs=PROGRAMS.filter(p=>p.bank===bank);return `<section class="bank-card"><h3>Mock ${bank} practice</h3><p>${qs.length} MCQs · ${programs.length} programs</p><div class="actions"><button class="primary" data-bank="${bank}" data-sample="yes">10 random questions →</button><button class="secondary" data-bank="${bank}">Complete collection</button><button class="text-button" data-program-filter="${bank}">Study its programs →</button></div></section>`;}).join('')}</div></details>`;}
function firstHalfHome(){const attempted=FIRST_HALF_MCQS.filter(q=>state.records[q.id]).length,correct=FIRST_HALF_MCQS.filter(q=>state.records[q.id]?.latestCorrect).length;paint(`${practiceTabs('first')}<div class="intro"><span class="eyebrow">PRACTICE SETS · WEEKS 1–6</span><h1>Build your Python foundations.</h1><p>600 MCQs with explanations: 100 per week. Trace code, test your understanding, and practise the core ideas before moving to Weeks 7–14.</p><p class="muted">${attempted} / 600 attempted · ${correct} currently correct · Instructor: Prof. Yanwei Wang</p><div class="actions"><button class="primary" data-first-start="mixed">24-question mixed round →</button><button class="secondary" data-first-start="missed">Revisit foundation mistakes</button></div><p class="code-info">A mixed round samples four questions from each week. Each snippet starts fresh. The 310 Mock A–D questions and 32 Studio originals are retained, alongside 258 new questions. Original questions without a week label are grouped by their foundation topic.</p></div><div class="bank-grid">${FIRST_HALF_WEEKS.map(w=>{const qs=FIRST_HALF_MCQS.filter(q=>firstWeek(q)===w.week),n=qs.filter(q=>state.records[q.id]).length,added=qs.filter(q=>q.bank==='foundation-new').length;return `<section class="panel bank-card"><span class="tag">WEEK ${w.week} · ${qs.length} MCQs</span><h2>${esc(w.name)}</h2><p>${esc(w.description)}</p><p class="muted">${n}/${qs.length} attempted · ${added} new questions</p><div class="actions"><button class="primary" data-first-start="${w.week}" data-first-sample="yes">10 random questions →</button><button class="secondary" data-first-start="${w.week}">Complete week</button><button class="text-button" data-first-browse="${w.week}">Browse questions ↓</button></div><a class="text-button" href="#materials">Weekly slides and notes →</a></section>`;}).join('')}</div><section class="half-browser" aria-labelledby="first-browser-title"><div class="section-heading"><div><h2 id="first-browser-title" tabindex="-1">Find a question</h2><p>Search by idea, code, topic, or question ID.</p></div><span id="first-count" class="muted" role="status"></span></div><div class="program-toolbar"><label class="search"><input id="first-search" type="search" value="${esc(firstSearch)}" placeholder="Search foundation questions…" aria-label="Search foundation questions"></label><label class="topic-select">Week <select id="first-week"><option value="all">All weeks</option>${FIRST_HALF_WEEKS.map(w=>`<option value="${w.week}" ${firstWeekFilter===String(w.week)?'selected':''}>Week ${w.week}</option>`).join('')}</select></label><label class="topic-select">Type <select id="first-type">${[['all','All types'],['code','Code questions'],['concept','Concepts']].map(([v,n])=>`<option value="${v}" ${v===firstType?'selected':''}>${n}</option>`).join('')}</select></label><label class="topic-select">Progress <select id="first-progress">${[['all','All progress'],['new','Not attempted'],['missed','Revisit'],['correct','Correct']].map(([v,n])=>`<option value="${v}" ${v===firstProgress?'selected':''}>${n}</option>`).join('')}</select></label><label class="topic-select">Source <select id="first-source">${[['all','All sources'],['foundation-new','New questions'],['studio','Studio originals'],['A','Mock A'],['B','Mock B'],['C','Mock C'],['D','Mock D']].map(([v,n])=>`<option value="${v}" ${v===firstSource?'selected':''}>${n}</option>`).join('')}</select></label><button class="text-button" data-first-clear="yes">Clear filters</button></div><div class="exercise-grid" id="first-list"></div><div id="first-pagination"></div></section>${originalMockCards()}<section class="collection-banner"><div><h2>Explore a concept in more depth</h2><p>Browse foundation topics or study the ten Week 6 teaching programs.</p></div><div class="actions"><a class="secondary" href="#practice">Topic practice →</a><button class="secondary" data-program-filter="lecture">Week 6 programs →</button></div></section>`,'banks/weeks-1-6');renderFirstList();}
function startFirst(value,short){let qs,label;if(value==='mixed'){qs=FIRST_HALF_WEEKS.flatMap(w=>sample(FIRST_HALF_MCQS.filter(q=>firstWeek(q)===w.week),4));qs=sample(qs,qs.length);label='Weeks 1–6 · Mixed practice';}else if(value==='missed'){qs=FIRST_HALF_MCQS.filter(q=>state.records[q.id]&&!state.records[q.id].latestCorrect);label='Weeks 1–6 · Revisit';}else{qs=FIRST_HALF_MCQS.filter(q=>firstWeek(q)===Number(value));if(short)qs=sample(qs,10);label='Week '+value+' · '+FIRST_HALF_WEEKS.find(w=>w.week===Number(value)).name;}if(!qs.length){document.getElementById('first-count').textContent='No missed foundation questions to revisit yet.';return;}startQuiz(qs.map(q=>q.id),label,'banks/weeks-1-6');}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.firstStart)startFirst(b.dataset.firstStart,!!b.dataset.firstSample);else if(b.dataset.firstQuestion)startQuiz([b.dataset.firstQuestion],'Week '+firstWeek(FIRST_HALF_MCQS.find(q=>q.id===b.dataset.firstQuestion))+' · Selected question','banks/weeks-1-6');else if(b.dataset.firstPage!==undefined){firstPage=Number(b.dataset.firstPage);renderFirstList();}else if(b.dataset.firstBrowse){firstWeekFilter=b.dataset.firstBrowse;firstType=firstProgress=firstSource='all';firstSearch='';firstPage=0;firstHalfHome();document.getElementById('first-browser-title').focus?.();document.getElementById('first-browser-title').scrollIntoView?.({behavior:'smooth'});}else if(b.dataset.firstClear){firstWeekFilter=firstType=firstProgress=firstSource='all';firstSearch='';firstPage=0;firstHalfHome();}});
document.addEventListener('input',e=>{if(e.target.id==='first-search'){firstSearch=e.target.value;firstPage=0;renderFirstList();}});
document.addEventListener('change',e=>{if(e.target.id==='first-week')firstWeekFilter=e.target.value;else if(e.target.id==='first-type')firstType=e.target.value;else if(e.target.id==='first-progress')firstProgress=e.target.value;else if(e.target.id==='first-source')firstSource=e.target.value;else return;firstPage=0;renderFirstList();});
